/**
 * @typedef {import('micromark-extension-gfm-footnote').HTMLOptions} HTMLOptions
 * @typedef {import('micromark-extension-gfm-strikethrough').Options} Options
 * @typedef {import('micromark-util-types').Extension} Extension
 * @typedef {import('micromark-util-types').HTMLExtension} HTMLExtension
 */

import {
  combineExtensions,
  combineHTMLExtensions
} from 'micromark-util-combine-extensions'
import {
  gfmAutolinkLiteral,
  gfmAutolinkLiteralHTML
} from 'micromark-extension-gfm-autolink-literal'
import {gfmFootnote, gfmFootnoteHTML} from 'micromark-extension-gfm-footnote'
import {
  gfmStrikethrough,
  gfmStrikethroughHTML
} from 'micromark-extension-gfm-strikethrough'
import {gfmTable, gfmTableHTML} from 'micromark-extension-gfm-table'
import {gfmTagfilterHTML} from 'micromark-extension-gfm-tagfilter'
import {
  gfmTaskListItem,
  gfmTaskListItemHTML
} from 'micromark-extension-gfm-task-list-item'

/**
 * Create an extension for `micromark` to enable GFM syntax.
 *
 * @param {Options | null | undefined} [options]
 *   Configuration (optional).
 *
 *   Passed to `micromark-extens-gfm-strikethrough`.
 * @returns {Extension}
 *   Extension for `micromark` that can be passed in `extensions` to enable GFM
 *   syntax.
 */
export function gfm(options) {
  return combineExtensions([
    gfmAutolinkLiteral(),
    gfmFootnote(),
    gfmStrikethrough(options),
    gfmTable(),
    gfmTaskListItem()
  ])
}

/**
 * Create an extension for `micromark` to support GFM when serializing to HTML.
 *
 * @param {HTMLOptions | null | undefined} [options]
 *   Configuration (optional).
 *
 *   Passed to `micromark-extens-gfm-footnote`.
 * @returns {HTMLExtension}
 *   Extension for `micromark` that can be passed in `htmlExtensions` to
 *   support GFM when serializing to HTML.
 */
export function gfmHTML(options) {
  return combineHTMLExtensions([
    gfmAutolinkLiteralHTML(),
    gfmFootnoteHTML(options),
    gfmStrikethroughHTML(),
    gfmTableHTML(),
    gfmTagfilterHTML(),
    gfmTaskListItemHTML()
  ])
}
